import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import styles from './NotificationBell.module.css';

const NotificationBell = () => {
    const navigate = useNavigate();
    const [isOpen, setIsOpen] = useState(false);
    const [notifications, setNotifications] = useState([]);
    const [unreadCount, setUnreadCount] = useState(0);
    const [loading, setLoading] = useState(false);
    const [nextPage, setNextPage] = useState(null);
    
    const dropdownRef = useRef(null);
    const listRef = useRef(null);

    // 1. Закрытие по клику снаружи
    useEffect(() => {
        const handleClickOutside = (event) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
                setIsOpen(false);
            }
        };
        document.addEventListener("mousedown", handleClickOutside);
        return () => document.removeEventListener("mousedown", handleClickOutside);
    }, []);

    // 2. POLLING: Обновляем уведомления каждые 5 секунд
    useEffect(() => {
        fetchNotifications(true);
        
        const interval = setInterval(() => {
            fetchNotifications(true, true); 
        }, 5000); // Уменьшил интервал для более быстрой синхронизации
        
        return () => clearInterval(interval);
    }, []);

    // 3. Функция загрузки
    const fetchNotifications = async (reset = false, silent = false) => {
        if (loading && !silent) return;
        if (!reset && !nextPage) return;
        if (!silent) setLoading(true);

        try {
            const token = localStorage.getItem('access');
            // Используем IP из твоего конфига
            const url = reset 
                ? 'http://10.124.215.133:8000/api/notifications/' 
                : nextPage;

            const resp = await axios.get(url, {
                headers: { 'Authorization': `Bearer ${token}` }
            });

            const newItems = resp.data.results || [];
            setNextPage(resp.data.next);

            if (reset) {
                setNotifications(newItems);
                // Считаем количество is_read: false
                const unread = newItems.filter(n => !n.is_read).length;
                setUnreadCount(unread);
            } else {
                setNotifications(prev => [...prev, ...newItems]);
            }
        } catch (err) {
            console.error("Ошибка уведомлений:", err);
        } finally {
            if (!silent) setLoading(false);
        }
    };

    // 4. "Прочитать все" с Оптимистичным обновлением
    const handleMarkAllRead = async (e) => {
        e.stopPropagation();
        
        // 1. Запоминаем старое состояние на случай ошибки
        const prevCount = unreadCount;
        const prevNotifications = [...notifications];

        // 2. МГНОВЕННО обновляем интерфейс (не ждем сервер)
        setUnreadCount(0);
        setNotifications(prev => prev.map(n => ({ ...n, is_read: true })));

        try {
            const token = localStorage.getItem('access');
            // Отправляем запрос на сервер
            await axios.post('http://10.124.215.133:8000/api/notifications/mark_all_read/', {}, {
                headers: { 'Authorization': `Bearer ${token}` }
            });
            
            // После успеха можно тихо обновить данные с сервера, чтобы убедиться в синхронизации
            fetchNotifications(true, true); 
            
        } catch (err) {
            console.error("Не удалось пометить как прочитанное", err);
            // 3. Если ошибка - откатываем изменения
            setUnreadCount(prevCount);
            setNotifications(prevNotifications);
            alert("Ошибка связи с сервером 😔");
        }
    };

    const handleScroll = (e) => {
        const { scrollTop, scrollHeight, clientHeight } = e.target;
        if (scrollHeight - scrollTop <= clientHeight + 50 && nextPage && !loading) {
            fetchNotifications(false);
        }
    };


    const handleItemClick = (notif) => {
        setIsOpen(false);
        if (notif.sender) {
            const target = notif.sender.handle || notif.sender.id;
            navigate(`/${target}`);
        }
    };

    return (
        <div className={styles.container} ref={dropdownRef}>
            {/* Колокольчик */}
            <div className={styles.bellWrapper} onClick={() => setIsOpen(!isOpen)}>
                <img src="images/bell.svg" alt="Bell" className={styles.bellIcon} />
                {/* Показываем бейдж только если count > 0 */}
                {unreadCount > 0 && (
                    <div className={styles.badge}>
                        {unreadCount > 9 ? '9+' : unreadCount}
                    </div>
                )}
            </div>

            {isOpen && (
                <div className={styles.dropdown}>
                    <div className={styles.header}>
                        <div className={styles.title}>Уведомления</div>
                        {unreadCount > 0 && (
                            <button className={styles.markReadBtn} onClick={handleMarkAllRead}>
                                ✓ Прочитать все
                            </button>
                        )}
                    </div>

                    <div className={styles.list} onScroll={handleScroll} ref={listRef}>
                        {notifications.length > 0 ? (
                            notifications.map((notif) => (
                                <div 
                                    key={notif.id} 
                                    className={`${styles.item} ${!notif.is_read ? styles.unread : ''}`}
                                    onClick={() => handleItemClick(notif)}
                                >
                                    <div className={styles.avatarContainer}>
                                        <img 
                                            src={notif.sender?.avatar || "images/profile.svg"} 
                                            className={styles.avatar} 
                                            alt="ava"
                                            onError={(e)=>{e.target.src="images/profile.svg"}}
                                        />
                                    </div>
                                    <div className={styles.content}>
                                        <div className={styles.text}>
                                            <span className={styles.name}>{notif.sender?.nickname}</span>
                                            {notif.text}
                                        </div>
                                        <div className={styles.date}>
                                            {new Date(notif.created_at).toLocaleDateString()}
                                        </div>
                                    </div>
                                    {!notif.is_read && <div className={styles.dot}></div>}
                                </div>
                            ))
                        ) : (
                            <div className={styles.empty}>Здесь пока тихо... 🍃</div>
                        )}

                        {loading && <div className={styles.loader}>Загрузка...</div>}
                        
                        {!loading && nextPage && (
                            <button className={styles.loadMoreBtn} onClick={(e) => { e.stopPropagation(); fetchNotifications(false); }}>
                                Показать еще
                            </button>
                        )}
                    </div>
                </div>
            )}
        </div>
    );
};

export default NotificationBell;
